CREATE TEMP TABLE fixture_values(key text PRIMARY KEY,value jsonb);
CREATE FUNCTION pg_temp.write_op(ops jsonb,ticket uuid DEFAULT NULL,preview boolean DEFAULT false) RETURNS jsonb LANGUAGE sql AS $$ SELECT public.payroll_correction_write('dd000000-0000-4000-8000-000000000010',ops,ticket,preview) $$;
CREATE FUNCTION pg_temp.day(d date) RETURNS jsonb LANGUAGE sql AS $$ SELECT public.payroll_schedule_days('dd000000-0000-4000-8000-000000000010',ARRAY['dd000000-0000-4000-8000-000000000040'::uuid],d,d)->0 $$;
CREATE FUNCTION pg_temp.review_op(d date) RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_build_array(jsonb_build_object('module','jornadas','action','approve','values',jsonb_build_object('employee_id','dd000000-0000-4000-8000-000000000040','work_date',d,'snapshot',pg_temp.day(d)->'snapshot','status','approved'))) $$;
SELECT pg_temp.assert(pg_temp.day('2026-09-05')->>'status'='pending','new administrative day pending');
SELECT pg_temp.write_op(pg_temp.review_op('2026-09-05')||pg_temp.review_op('2026-09-06'));
SELECT pg_temp.assert(pg_temp.day('2026-09-05')->>'status'='approved','administrative/rest days approved together');
SELECT pg_temp.denied($q$SELECT pg_temp.write_op('[{"module":"jornadas","action":"approve","values":{"employee_id":"dd000000-0000-4000-8000-000000000041","work_date":"2026-09-05","snapshot":{},"status":"approved"}}]')$q$,'22023');
INSERT INTO fixture_values VALUES('stale',pg_temp.review_op('2026-09-05'));
SELECT pg_temp.write_op('[{"module":"jornadas","action":"create","id":"dd000000-0000-4000-8000-000000000120","values":{"employee_id":"dd000000-0000-4000-8000-000000000040","assignment_date":"2026-09-05","shift_id":"dd000000-0000-4000-8000-000000000110"}}]');
SELECT pg_temp.assert(pg_temp.day('2026-09-05')->>'status'='pending','assignment invalidates administrative approval');
SELECT pg_temp.assert(pg_temp.day('2026-09-06')->>'status'='approved','unmodified adjacent day stays approved');
RESET ROLE;
