CREATE FUNCTION pg_temp.fail_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit failure'; END $$;
CREATE TRIGGER fixture_fail_audit BEFORE INSERT ON public.payroll_correction_events FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_audit();
SET LOCAL ROLE authenticated;
SELECT pg_temp.denied($q$SELECT pg_temp.write_op('[{"module":"novedades","action":"update","id":"dd000000-0000-4000-8000-000000000080","values":{"hours":8}}]',pg_temp.ticket())$q$,'P0001');
SELECT pg_temp.assert((SELECT hours=3 FROM public.payroll_novelties WHERE id='dd000000-0000-4000-8000-000000000080'),'audit failure rolls back content');
RESET ROLE;
DROP TRIGGER fixture_fail_audit ON public.payroll_correction_events;
CREATE FUNCTION pg_temp.slow_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM pg_sleep(0.2); RETURN NEW; END $$;
CREATE TRIGGER fixture_slow_audit BEFORE INSERT ON public.payroll_correction_events FOR EACH ROW EXECUTE FUNCTION pg_temp.slow_audit();
UPDATE public.payroll_correction_tickets SET expires_at=clock_timestamp()+interval '0.15 seconds' WHERE id=pg_temp.ticket();
SET LOCAL ROLE authenticated;
SELECT pg_temp.denied($q$SELECT pg_temp.write_op('[{"module":"novedades","action":"update","id":"dd000000-0000-4000-8000-000000000080","values":{"hours":6}}]',pg_temp.ticket())$q$);
SELECT pg_temp.assert((SELECT hours=3 FROM public.payroll_novelties WHERE id='dd000000-0000-4000-8000-000000000080'),'expiry during save rolls back content and audit');
RESET ROLE;
DROP TRIGGER fixture_slow_audit ON public.payroll_correction_events;
